<script setup lang="ts">
import { computed, onUnmounted, reactive, ref } from 'vue'
import type { Settings, Status, Trial } from './api'
import { useConsole } from './context'
const props=defineProps<{settings:Settings}>(),emit=defineEmits<{saved:[settings:Settings]}>(),{api,run,notify}=useConsole()
const draft=reactive({...props.settings,record_paths:[...(props.settings.record_paths||[])]}),paths=ref(draft.record_paths.join('\n'))
const devices=ref<{video:[string,string][];audio:[string,string][];encoders:string[]}>({video:[],audio:[],encoders:[]}),deviceInfo=ref('')
const saving=ref(false),testId=ref(''),testState=ref(''),testReady=ref(false),confirmed=ref(false),testURL=ref('')
const capture=computed(()=>draft.role==='integrated'||draft.role==='station')
let poll:ReturnType<typeof setInterval>|undefined
async function save(){saving.value=true;try{draft.record_paths=paths.value.split('\n').map(p=>p.trim()).filter(Boolean);await api.request('/v1/commands/configure',draft);const result=await api.request<Status>('/v1/status');Object.assign(draft,result.settings);emit('saved',result.settings);testId.value='';testReady.value=false;confirmed.value=false;notify('设置已保存。设备更改后请重新试录；监听地址更改需重启后台。')}finally{saving.value=false}}
async function discover(){devices.value=await api.request('/v1/setup/devices',{});deviceInfo.value=`发现 ${devices.value.video.length} 个视频设备；FFmpeg 编码器：${devices.value.encoders.join('、')}`}
async function modes(){deviceInfo.value=(await api.request<{modes:string}>('/v1/setup/devices',{kind:'modes',camera:draft.camera})).modes}
async function trial(){const result=await api.request<Trial>('/v1/setup/test',{});testId.value=result.id;testReady.value=false;confirmed.value=false;testState.value='正在试录，等待摄像头启动和文件校验…';clearInterval(poll);poll=setInterval(()=>void run(async()=>{const r=await api.request<Trial>('/v1/tests/'+testId.value);if(r.state==='running')return;clearInterval(poll);if(r.state==='error'){testState.value=r.error||'试录失败';return}testReady.value=true;testState.value=`试录完成：${r.duration?.toFixed(1)} 秒。请检查画面、声音和同步。`}),1500)}
async function playTrial(){if(testURL.value)await api.release({url:testURL.value,expires_in:0});testURL.value=(await api.media({test_id:testId.value})).url}
async function speech(){await api.request('/v1/setup/speech',{});notify('已向打包桌面发送测试播报，请确认桌面正在运行且中文语音服务可用。')}
async function finish(){if(!confirmed.value)throw new Error('请先检查回放并勾选确认');await api.request('/v1/setup/complete',{test_id:testId.value||null});const result=await api.request<Status>('/v1/status');emit('saved',result.settings);testState.value='首次配置已完成，可以回到桌面扫码打包。';notify(testState.value)}
onUnmounted(()=>{clearInterval(poll);if(testURL.value)void api.release({url:testURL.value,expires_in:0}).catch(()=>{})})
</script>
<template><div class="info-note" v-if="!settings.setup_complete"><strong>完成首次配置</strong><p>先设置设备和保存目录，再保存设置、进行 3 秒试录并确认回放。打包桌面只需负责预览和扫码。</p></div><form @submit.prevent="run(save)"><section class="card"><div class="section-title"><div><h2>节点与运行角色</h2><p class="muted">默认本机录像与保存一体，后续可接入多个打包工位。</p></div></div><div class="form-grid"><label>工位名称<input v-model="draft.station_name" required maxlength="80"></label><label>运行角色<select v-model="draft.role"><option value="integrated">本机录像 + 中心保存</option><option value="station">录像工位</option><option value="center">只做保存中心</option><option value="viewer">只读查看</option></select></label><label class="full">节点 ID<input :value="draft.station_id" readonly class="mono"></label><label>Web 访问<select v-model="draft.web_bind"><option value="127.0.0.1">仅本机</option><option value="0.0.0.0">允许局域网，重启后生效</option></select></label></div></section>
<section class="card"><h2>保存目录与保留策略</h2><div class="form-grid"><label>主录像目录<input v-model="draft.record_path" required></label><label>附加录像目录<textarea v-model="paths" rows="3" placeholder="每行一个，需提前创建或挂载"></textarea></label><label>自动清理<select v-model="draft.cleanup_policy"><option value="disabled">关闭自动清理</option><option value="verified">只清理已验证备份的录像</option><option value="local">纯本地循环，上传缓存仍受保护</option></select></label><label>本地保留天数<input v-model.number="draft.retention_days" type="number" min="1" max="3650" required></label><label>预警 / 清理水位 GB<input v-model.number="draft.disk_warn_gb" type="number" min="1" required></label><label>禁止录制水位 GB<input v-model.number="draft.disk_critical_gb" type="number" min="1" required></label></div></section>
<section class="card"><h2>备份目标</h2><div class="form-grid"><label>上传方式<select v-model="draft.upload_kind"><option value="none">不上传，仅本地保存</option><option value="directory">挂载目录 / NAS</option><option value="center">其他 PackRecord 保存中心</option></select></label><label v-if="draft.upload_kind==='directory'">目标目录<input v-model="draft.upload_path" placeholder="已挂载的 SMB / NFS 目录"></label><template v-if="draft.upload_kind==='center'"><label>中心地址<input v-model="draft.upload_url" placeholder="http://192.168.1.10:18765"></label><label>中心上传密钥<input v-model="draft.upload_token" type="password" autocomplete="off"></label></template></div><p class="fine">新设置用于新任务。队列保留原目标，上传确认不会立即删除本地原片。</p></section>
<section class="card"><div class="section-title"><div><h2>采集设备</h2><p class="muted">按设备实际能力选择；编码器能否使用以试录为准。</p></div><button id="discover" type="button" @click="run(discover)">刷新设备</button></div><datalist id="cameralist"><option v-for="[name,value] in devices.video" :key="value" :value="value" :label="name"/></datalist><datalist id="miclist"><option v-for="[name,value] in devices.audio" :key="value" :value="value" :label="name"/></datalist><div class="form-grid"><label>摄像头<input id="camera" v-model="draft.camera" list="cameralist" placeholder="/dev/v4l/by-id/…"></label><label>麦克风<input v-model="draft.microphone" list="miclist" placeholder="default"></label><label>音频接口<select v-model="draft.audio_backend"><option value="pulse">PulseAudio / PipeWire</option><option value="alsa">ALSA</option></select></label><label>输入格式<select v-model="draft.input_format"><option value="auto">自动</option><option value="mjpeg">MJPEG</option><option value="yuyv422">YUYV422</option><option value="nv12">NV12</option></select></label><label>画面宽度<input v-model.number="draft.width" type="number" min="160" max="7680" step="2" required></label><label>画面高度<input v-model.number="draft.height" type="number" min="120" max="4320" step="2" required></label><label>帧率<input v-model.number="draft.fps" type="number" min="1" max="120" required></label><label>编码器<select v-model="draft.encoder"><option value="hevc_qsv">Intel QSV · H.265</option><option value="h264_qsv">Intel QSV · H.264</option><option value="libx264">CPU · H.264</option><option value="libx265">CPU · H.265</option></select></label><label>质量值，越低越清晰<input v-model.number="draft.quality" type="number" min="1" max="51" required></label><label>编码速度<select v-model="draft.preset"><option>veryfast</option><option>faster</option><option>fast</option><option>medium</option><option>slow</option></select></label><label>最长单段分钟<input v-model.number="draft.max_record_minutes" type="number" min="1" max="1440" required></label><label class="check"><input v-model="draft.audio_enabled" type="checkbox">录制麦克风声音</label></div><div class="toolbar"><button type="button" @click="run(modes)">查看摄像头支持格式</button></div><pre v-if="deviceInfo" id="deviceinfo">{{ deviceInfo }}</pre></section>
<section class="card"><h2>订单语音</h2><div class="switch-grid"><label class="check"><input v-model="draft.speech_enabled" type="checkbox">开启订单语音</label><label class="check"><input v-model="draft.speech_quantity" type="checkbox">多件商品提醒</label><label class="check"><input v-model="draft.speech_remarks" type="checkbox">留言 / 备注 / 商品播报</label><label class="check"><input v-model="draft.speech_refund" type="checkbox">退款警告</label></div><label class="short">订单信息有效小时数<input v-model.number="draft.order_valid_hours" type="number" min="1" max="168" required></label></section><div class="sticky-actions"><span class="muted">修改前先停止录像或预览</span><button class="primary" :disabled="saving">{{ saving?'正在保存…':'保存工位设置' }}</button></div></form>
<section class="card"><div class="section-title"><div><h2>试录与配置确认</h2><p class="muted">使用已保存设置试录，试录文件不计入订单录像。</p></div><span class="badge" :class="settings.setup_complete?'green':'amber'">{{ settings.setup_complete?'已完成配置':'尚未完成' }}</span></div><div class="toolbar"><button v-if="capture" id="testrecord" @click="run(trial)">开始 3 秒试录</button><button @click="run(speech)">在打包桌面测试语音</button><button v-if="capture" id="playtest" :disabled="!testReady" @click="run(playTrial)">回放试录</button></div><p class="muted" id="teststate">{{ testState }}</p><video v-if="testURL" id="testplayer" :src="testURL" controls playsinline/><p class="fine">浏览器不支持原始 MKV/H.265 时，可通过本机备用向导检查回放。</p><p><label class="check"><input id="testconfirmed" v-model="confirmed" type="checkbox">已检查画面、声音和同步；无摄像头角色可直接确认</label></p><button id="finishsetup" class="primary" :disabled="!confirmed||(capture&&!testReady)" @click="run(finish)">确认首次配置完成</button></section></template>
